// Аккордеон (Преимущества)
const accordionItems = document.querySelectorAll('.accordion-item');

accordionItems.forEach(item => {
  item.addEventListener('click', () => {
    item.classList.toggle('active');
  });
});

// Карусель отзывов (Автопрокрутка)
let currentReviewIndex = 0;
const reviews = document.querySelectorAll('.review');
const totalReviews = reviews.length;

function showReview(index) {
  reviews.forEach((review, i) => {
    review.classList.remove('active');
    if (i === index) {
      review.classList.add('active');
    }
  });
}

// Запускаем автопрокрутку с интервалом 5 секунд
setInterval(() => {
  currentReviewIndex = (currentReviewIndex + 1) % totalReviews; // Переходим к следующему отзыву
  showReview(currentReviewIndex); // Показываем следующий отзыв
}, 5000);

// Инициализация показа первого отзыва
showReview(currentReviewIndex);

// Форма обратной связи (отправка данных на сервер)
const contactForm = document.querySelector('.contact-form');
const contactName = document.querySelector('.contact-form input[name="name"]');
const contactEmail = document.querySelector('.contact-form input[name="email"]');
const contactMessage = document.querySelector('.contact-form textarea[name="message"]');

contactForm.addEventListener('submit', (e) => {
  e.preventDefault();
  const name = contactName.value.trim();
  const email = contactEmail.value.trim();
  const message = contactMessage.value.trim();

  if (name && email && message) {
    const formData = new FormData();
    formData.append('name', name);
    formData.append('email', email);
    formData.append('message', message);

    fetch('sendform.php', {
      method: 'POST',
      body: formData,
    })
    .then(response => response.json())
    .then(data => {
      if (data.success) {
        alert('Сообщение отправлено успешно!');
        contactName.value = '';
        contactEmail.value = '';
        contactMessage.value = '';
      } else {
        alert('Произошла ошибка при отправке сообщения. Попробуйте еще раз.');
      }
    })
    .catch(error => {
      alert('Ошибка при отправке формы. Пожалуйста, попробуйте позже.');
      console.error(error);
    });
  } else {
    alert('Пожалуйста, заполните все поля формы.');
  }
});

// Плавная прокрутка к якорям
const anchorLinks = document.querySelectorAll('a[href^="#"]');

anchorLinks.forEach(anchor => {
  anchor.addEventListener('click', (e) => {
    e.preventDefault();
    const targetId = anchor.getAttribute('href').substring(1);
    const targetElement = document.getElementById(targetId);

    if (targetElement) {
      window.scrollTo({
        top: targetElement.offsetTop - 20,
        behavior: 'smooth',
      });
    }
  });
});

// Кнопка "Наверх"
const toTopButton = document.querySelector('.to-top');

window.addEventListener('scroll', () => {
  if (window.scrollY > 300) {
    toTopButton.style.display = 'block';
  } else {
    toTopButton.style.display = 'none';
  }
});

toTopButton.addEventListener('click', () => {
  window.scrollTo({
    top: 0,
    behavior: 'smooth',
  });
});
